  auth: "NEON_AUTH_BASE_URL" | "NEON_AUTH_JWKS_URL";
  dataApi: "NEON_DATA_API_URL";
  realtime: "NEON_REALTIME_URL" | "NEON_REALTIME_SECRET";
  storage: "AWS_ACCESS_KEY_ID" | "AWS_SECRET_ACCESS_KEY" | "AWS_ENDPOINT_URL_S3" | "AWS_REGION";
